window.HistoryAtlas.PERSONS_LINKS = [["sun-wu","wu-zixu",-512,"吴王阖庐与伍子胥、孙武伐楚拔舒，孙武以民劳谏止入郢。","史料确证","《史记·伍子胥列传》"],["darius-i","xerxes-i",-498,"大流士一世立其子薛西斯为王储。","史料确证","希罗多德《历史》卷七"],["socrates","plato",-407,"柏拉图约二十岁起追随苏格拉底学习哲学，此后长期从游。","史料确证","柏拉图《申辩篇》；第欧根尼·拉尔修《名哲言行录》卷三"],["socrates","plato",-399,"苏格拉底受审时柏拉图在场，并表示愿为其担保罚金。","史料确证","柏拉图《申辩篇》"],["plato","aristotle",-367,"亚里士多德十七岁入柏拉图学园，师从柏拉图约二十年。","史料确证","第欧根尼·拉尔修《名哲言行录》卷五"],["aristotle","alexander-the-great",-343,"亚里士多德应腓力二世之聘，在米埃扎教导少年亚历山大。","史料确证","普鲁塔克《亚历山大传》"],["hannibal","scipio-africanus",-218,"提契努斯河之战中，少年西庇阿随父迎战汉尼拔，冲阵救出负伤的父亲。","史料确证","波利比乌斯《历史》卷十；李维《建城以来史》卷二十一"],["xiang-yu","han-xin",-208,"项梁死后韩信属项羽为郎中，数以策干项羽，不用。","史料确证","《史记·淮阴侯列传》"],["liu-bang","xiang-yu",-206,"项羽率诸侯军入关，在鸿门宴会刘邦。","史料确证","《史记·项羽本纪》"],["liu-bang","han-xin",-206,"韩信经萧何力荐，被刘邦拜为大将。","史料确证","《史记·淮阴侯列传》"],["liu-bang","xiang-yu",-203,"刘邦与项羽临广武涧对话，数项羽十罪，为弩所中。","史料确证","《史记·项羽本纪》《史记·高祖本纪》"],["hannibal","scipio-africanus",-202,"扎马会战前两人当面会谈，随后西庇阿击败汉尼拔。","史料确证","波利比乌斯《历史》卷十五；李维《建城以来史》卷三十"],["liu-bang","xiang-yu",-202,"刘邦会诸侯军围项羽于垓下，项羽败亡。","史料确证","《史记·项羽本纪》"],["han-xin","xiang-yu",-202,"韩信率齐兵会汉王于垓下，围攻项羽。","史料确证","《史记·淮阴侯列传》"],["liu-bang","han-xin",-201,"刘邦伪游云梦，会诸侯于陈，执楚王韩信。","史料确证","《史记·高祖本纪》《史记·淮阴侯列传》"],["wei-qing","huo-qu-bing",-123,"霍去病为票姚校尉随舅父卫青出定襄击匈奴，封冠军侯。","史料确证","《史记·卫将军骠骑列传》"],["wei-qing","zhang-qian",-123,"张骞以校尉从大将军卫青击匈奴，因知水草处，军得以不乏，封博望侯。","史料确证","《史记·卫将军骠骑列传》"],["li-guang","zhang-qian",-121,"李广与张骞分道出右北平，李广被围，张骞军后期而至解围。","史料确证","《史记·李将军列传》"],["wei-qing","li-guang",-119,"漠北之战李广为前将军从卫青出塞，迷道失期，归幕府后自刭。","史料确证","《史记·李将军列传》"],["julius-caesar","cleopatra-vii",-48,"克娄巴特拉潜入亚历山大里亚王宫面见恺撒，恺撒扶立其复位。","史料确证","普鲁塔克《恺撒传》；恺撒《内战记》"],["julius-caesar","augustus",-45,"屋大维赴西班牙追随恺撒军中，随后被恺撒在遗嘱中收为养子。","史料确证","苏埃托尼乌斯《罗马十二帝王传·奥古斯都传》；尼古拉斯《奥古斯都传》"],["augustus","cleopatra-vii",-31,"亚克兴海战中屋大维击败安东尼与克娄巴特拉的联军。","史料确证","普鲁塔克《安东尼传》；狄奥《罗马史》卷五十"],["augustus","cleopatra-vii",-30,"屋大维攻入亚历山大里亚后与克娄巴特拉会面，其后她自杀。","史料确证","普鲁塔克《安东尼传》；狄奥《罗马史》卷五十一"],["trajan","hadrian",86,"哈德良十岁丧父，由同乡亲族图拉真等任监护人。","史料确证","《罗马君王传·哈德良传》"],["trajan","hadrian",117,"图拉真临终前收哈德良为养子，其真实性古人已有疑议。","学界推测","《罗马君王传·哈德良传》；狄奥《罗马史》卷六十九"],["hadrian","marcus-aurelius",138,"哈德良立安敦宁为嗣时，令其同时收少年马可为养子。","史料确证","《罗马君王传·马可·奥勒留传》"],["liu-bei","guan-yu",184,"刘备于乡里合徒众，关羽与张飞为之御侮，恩若兄弟。","史料确证","《三国志·蜀书·关羽传》"],["cao-cao","liu-bei",198,"刘备失徐州后归曹操，随还许都，曹操谓天下英雄唯刘备与己。","史料确证","《三国志·蜀书·先主传》"],["cao-cao","guan-yu",200,"曹操东征擒关羽，拜偏将军，关羽斩颜良报效后告辞奔刘备。","史料确证","《三国志·蜀书·关羽传》"],["liu-bei","zhuge-liang",207,"刘备三顾诸葛亮于隆中，诸葛亮陈三分天下之策，遂出山辅佐。","史料确证","《三国志·蜀书·诸葛亮传》"],["cao-cao","liu-bei",208,"曹操以精骑追及刘备于当阳长坂，后在赤壁为孙刘联军所败。","史料确证","《三国志·蜀书·先主传》"],["cao-cao","sun-quan",208,"曹操致书孙权相威胁，孙权遣周瑜等与刘备并力，赤壁大破曹军。","史料确证","《三国志·吴书·吴主传》；裴注引《江表传》"],["cao-cao","sima-yi",208,"曹操为丞相，辟司马懿为文学掾，使与太子游处。","史料确证","《晋书·宣帝纪》"],["zhuge-liang","sun-quan",208,"诸葛亮出使柴桑，说孙权与刘备联合抗曹。","史料确证","《三国志·蜀书·诸葛亮传》"],["liu-bei","sun-quan",210,"刘备至京口见孙权，求都督荆州。","史料确证","《三国志·蜀书·先主传》《三国志·吴书·吴主传》"],["cao-cao","sun-quan",213,"曹操攻濡须，孙权亲自相拒月余，曹操望见吴军齐肃乃退。","史料确证","《三国志·吴书·吴主传》"],["guan-yu","zhuge-liang",214,"关羽闻马超来降，致书诸葛亮问其人才，诸葛亮复书称其不如关羽。","史料确证","《三国志·蜀书·关羽传》"],["cao-cao","liu-bei",219,"刘备据定军山斩夏侯渊，曹操亲至汉中争夺，不得而还。","史料确证","《三国志·蜀书·先主传》"],["guan-yu","sun-quan",219,"孙权遣吕蒙袭取荆州，关羽败走麦城，被孙权部将擒杀。","史料确证","《三国志·吴书·吴主传》《三国志·蜀书·关羽传》"],["liu-bei","zhuge-liang",223,"刘备病笃于永安，托孤于丞相诸葛亮。","史料确证","《三国志·蜀书·诸葛亮传》"],["zhuge-liang","sima-yi",231,"诸葛亮攻祁山，司马懿都督雍凉诸军拒之于上邽、卤城一带。","史料确证","《晋书·宣帝纪》；《三国志·蜀书·诸葛亮传》"],["zhuge-liang","sima-yi",234,"诸葛亮出斜谷屯五丈原，与司马懿对峙百余日，病卒军中。","史料确证","《三国志·蜀书·诸葛亮传》；《晋书·宣帝纪》"],["diocletian","constantine-the-great",301,"君士坦丁青年时留居戴克里先宫廷，随皇帝巡行东方。","史料确证","优西比乌《君士坦丁传》；拉克坦提乌斯《迫害者之死》"],["wang-xizhi","xie-an",353,"永和九年三月三日，王羲之与谢安等四十一人修禊于兰亭。","史料确证","王羲之《兰亭集序》；《晋书·王羲之传》"],["liu-yu","tao-yuanming",404,"陶渊明出为镇军参军，镇军将军一说即刘裕。","学界推测","陶渊明《始作镇军参军经曲阿》；《宋书·陶潜传》"],["bei-wei-xiaowendi","li-daoyuan",494,"郦道元以尚书郎从孝文帝北巡阴山一带。","史料确证","郦道元《水经注》卷三"],["justinian-i","belisarius",527,"贝利撒留以查士丁尼近卫身份受命统率达拉要塞驻军。","史料确证","普罗科匹厄斯《战史》卷一"],["justinian-i","belisarius",532,"尼卡暴动中贝利撒留奉查士丁尼之命在竞技场镇压暴动。","史料确证","普罗科匹厄斯《战史》卷一"],["tang-taizong","li-jing",617,"李靖被李渊所执，经李世民请求获释，此后从李世民征战。","史料确证","《旧唐书·李靖传》"],["tang-taizong","li-jing",630,"李靖受唐太宗之命北伐，大破东突厥，擒颉利可汗。","史料确证","《旧唐书·李靖传》《旧唐书·太宗本纪》"],["tang-taizong","wu-zetian",637,"武则天入宫为唐太宗才人。","史料确证","《旧唐书·则天皇后本纪》"],["tang-taizong","xuan-zang",645,"玄奘西行归来，在洛阳宫谒见唐太宗，太宗劝其还俗辅政，玄奘辞之。","史料确证","慧立、彦悰《大慈恩寺三藏法师传》"],["wu-zetian","xuan-zang",656,"武后临产，遣使请玄奘祈福，所生皇子李显号佛光王，度为玄奘弟子。","史料确证","慧立、彦悰《大慈恩寺三藏法师传》卷九"],["li-bai","du-fu",744,"李白赐金放还后与杜甫相识于洛阳，同游梁宋，次年又同游东鲁。","史料确证","杜甫《赠李白》；李白《沙丘城下寄杜甫》"],["charlemagne","harun-al-rashid",801,"哈伦·拉希德的使节在意大利觐见查理曼，双方互通使节并赠送礼物。","史料确证","《法兰克王国编年史》；艾因哈德《查理大帝传》"],["han-yu","liu-zongyuan",803,"韩愈与柳宗元同任监察御史，此后交谊终身。","史料确证","韩愈《柳子厚墓志铭》"],["han-yu","bai-ju-yi",822,"韩愈作诗寄白居易约游曲江，白居易作诗相酬。","史料确证","韩愈《同水部张员外籍曲江春游寄白二十二舍人》；白居易《酬韩侍郎张博士雨后游曲江见寄》"],["wang-anshi","sima-guang",1070,"司马光致书王安石论新法之弊，王安石作《答司马谏议书》回复。","史料确证","司马光《与王介甫书》；王安石《答司马谏议书》"],["wang-anshi","shen-kuo",1073,"沈括受王安石信用参与推行新法，奉命察访两浙农田水利。","史料确证","《宋史·沈括传》；李焘《续资治通鉴长编》"],["wang-anshi","su-shi",1084,"苏轼自黄州移汝州途中过江宁，访退居钟山的王安石，同游唱和。","史料确证","《宋史·苏轼传》；苏轼《次荆公韵四绝》"],["sima-guang","su-shi",1086,"司马光入相后召苏轼还朝，两人就免役法当面争论。","史料确证","《宋史·苏轼传》"],["lu-you","zhu-xi",1182,"朱熹提举浙东常平救荒，陆游作诗相寄，两人有书信往来。","学界推测","陆游《寄朱元晦提举》"],["richard-i","saladin",1191,"理查一世在阿苏夫之战中击败萨拉丁亲率的军队。","史料确证","巴哈丁《萨拉丁传》；《理查国王行纪》"],["richard-i","saladin",1192,"雅法之战后双方经使节谈判订立停战协定。","史料确证","巴哈丁《萨拉丁传》；《理查国王行纪》"],["zhu-xi","xin-qiji",1192,"辛弃疾任福建提点刑狱期间往访朱熹，朱熹为其题写斋名。","学界推测","《宋史·辛弃疾传》；朱熹文集"],["lu-you","xin-qiji",1203,"辛弃疾知绍兴府时与闲居山阴的陆游交往，次年陆游作诗送其入朝。","史料确证","陆游《送辛幼安殿撰造朝》"],["genghis-khan","yelu-chucai",1218,"成吉思汗征召耶律楚材北上入见，留侍左右。","史料确证","《元史·耶律楚材传》"],["qiu-chuji","yelu-chucai",1221,"丘处机西行抵撒马尔罕，与随成吉思汗西征的耶律楚材相识唱和。","史料确证","李志常《长春真人西游记》；耶律楚材《西游录》"],["genghis-khan","qiu-chuji",1222,"成吉思汗在兴都库什山行营接见丘处机，问长生之道。","史料确证","李志常《长春真人西游记》；《元史·丘处机传》"],["genghis-khan","kublai",1224,"成吉思汗西征归来，年幼的忽必烈与旭烈兀迎于叶密立河畔，行狩猎拭指之礼。","史料确证","拉施特《史集》"],["kublai","marco-polo",1275,"马可·波罗随父叔抵上都觐见忽必烈，此事仅见于其本人游记。","学界推测","《马可·波罗游记》"],["kublai","wen-tianxiang",1282,"忽必烈召见被囚的文天祥，劝其出仕，文天祥不从，旋就义。","史料确证","《宋史·文天祥传》"],["timur","ibn-khaldun",1401,"大马士革被围期间，伊本·赫勒敦缒城而出，在帖木儿营中与其多次会谈。","史料确证","伊本·赫勒敦《自传》"],["isabella-i-of-castile","christopher-columbus",1486,"哥伦布首次觐见伊莎贝拉一世与斐迪南二世，陈述西航计划。","史料确证","费尔南多·哥伦布《海军上将传》；拉斯·卡萨斯《印度群岛史》"],["isabella-i-of-castile","christopher-columbus",1493,"伊莎贝拉一世在巴塞罗那接见首航归来的哥伦布，批准第二次远航。","史料确证","费尔南多·哥伦布《海军上将传》"],["charles-v","ferdinand-magellan",1518,"麦哲伦在巴利亚多利德觐见查理五世，订立航往香料群岛的协议。","史料确证","皮加费塔《首次环球航行记》；《巴利亚多利德协定》"],["charles-v","martin-luther",1521,"路德在沃尔姆斯帝国议会上当着查理五世拒绝撤回其著作。","史料确证","《沃尔姆斯帝国议会文献》"],["charles-v","hernan-cortes",1528,"科尔特斯回西班牙觐见查理五世，次年受封瓦哈卡谷侯爵。","史料确证","戈马拉《征服墨西哥史》"],["charles-v","francisco-pizarro",1528,"皮萨罗在托莱多觐见查理五世，次年获颁征服秘鲁的协定。","史料确证","《托莱多协定》；谢萨·德·莱昂《秘鲁纪事》"],["hernan-cortes","francisco-pizarro",1528,"科尔特斯与皮萨罗同在西班牙，据记载曾相见。","学界推测","戈马拉《西印度通史》"],["oda-nobunaga","tokugawa-ieyasu",1562,"德川家康与织田信长结成清洲同盟。","史料确证","《信长公记》；《三河物语》"],["qi-jiguang","zhang-juzheng",1568,"张居正主政时调戚继光北上镇守蓟镇，并长期书信支持其练兵。","史料确证","《明史·戚继光传》；张居正《张太岳集》书牍"],["elizabeth-i","ivan-iv",1570,"伊凡四世致信伊丽莎白一世，责其未缔结同盟，两人此前已有书信往来。","史料确证","伊凡四世致伊丽莎白一世书（1570年）"],["oda-nobunaga","toyotomi-hideyoshi",1573,"秀吉早年仕于织田信长，1573年因攻灭浅井氏之功受封北近江长浜。","史料确证","《信长公记》"],["oda-nobunaga","tokugawa-ieyasu",1575,"织田信长与德川家康联军在长篠之战中大败武田胜赖。","史料确证","《信长公记》"],["tokugawa-ieyasu","toyotomi-hideyoshi",1584,"德川家康与秀吉在小牧·长久手对阵，后议和并臣从秀吉。","史料确证","《三河物语》；《当代记》"],["nurhaci","yuan-chonghuan",1626,"宁远之战中袁崇焕凭坚城与西洋大炮击退努尔哈赤亲率的后金军。","史料确证","《明史·袁崇焕传》；《清太祖实录》"],["kangxi","qianlong",1722,"康熙帝在圆明园牡丹台初见皇孙弘历，随后命其入宫养育。","史料确证","《清高宗实录》；乾隆《御制诗》自注"],["benjamin-franklin","george-washington",1775,"富兰克林作为大陆会议委员赴坎布里奇大陆军营，与华盛顿商议军务。","史料确证","华盛顿书信；大陆会议记录"],["alexander-von-humboldt","johann-wolfgang-von-goethe",1794,"洪堡在耶拿与歌德交往，共同讨论解剖学与自然研究。","史料确证","歌德日记与书信；洪堡书信"],["napoleon-bonaparte","toussaint-louverture",1801,"卢维杜尔将圣多明各宪法呈交拿破仑，拿破仑复信并遣勒克莱尔率军前往。","史料确证","拿破仑致卢维杜尔书（1801年11月）"],["alexander-von-humboldt","simon-bolivar",1804,"玻利瓦尔在巴黎结识刚从美洲归来的洪堡。","学界推测","玻利瓦尔书信；洪堡书信"],["horatio-nelson","duke-of-wellington",1805,"纳尔逊与威灵顿在伦敦殖民地部候见室中唯一一次相遇交谈。","史料确证","克罗克《克罗克文书》所录威灵顿回忆"],["napoleon-bonaparte","johann-wolfgang-von-goethe",1808,"埃尔福特会议期间拿破仑接见歌德并谈论《少年维特之烦恼》。","史料确证","歌德《与拿破仑的会见》"],["napoleon-bonaparte","duke-of-wellington",1815,"滑铁卢战役中威灵顿与布吕歇尔联军击败拿破仑亲率的法军。","史料确证","威灵顿滑铁卢战报（1815年6月19日）"],["jose-de-san-martin","simon-bolivar",1822,"圣马丁与玻利瓦尔在瓜亚基尔闭门会晤。","史料确证","圣马丁与玻利瓦尔往来书信"],["lin-zexu","wei-yuan",1841,"林则徐遣戍途经京口，与魏源相晤，以所辑《四洲志》等资料托其编撰《海国图志》。","史料确证","魏源《海国图志·叙》"],["alexander-von-humboldt","charles-darwin",1842,"达尔文在伦敦默奇森家中与洪堡会面。","史料确证","达尔文《自传》"],["lin-zexu","zuo-zongtang",1849,"林则徐归乡途经长沙，邀左宗棠至湘江舟中彻夜长谈。","史料确证","《左宗棠年谱》；左宗棠书信"],["queen-victoria","florence-nightingale",1856,"维多利亚女王在巴尔莫勒尔接见南丁格尔，听取军队卫生改革意见。","史料确证","维多利亚女王日记"],["queen-victoria","david-livingstone",1857,"利文斯通首次归国期间获维多利亚女王接见。","学界推测","布莱基《利文斯通传》"],["zeng-guofan","li-hongzhang",1859,"李鸿章入曾国藩幕府襄办营务，后于1861年受命回籍招募淮军。","史料确证","《清史稿·李鸿章传》"],["zeng-guofan","zuo-zongtang",1860,"左宗棠以四品京堂襄办曾国藩军务，募练楚军。","史料确证","《清史稿·左宗棠传》"],["david-livingstone","henry-morton-stanley",1871,"斯坦利在坦噶尼喀湖畔乌吉吉找到利文斯通，随后同行考察。","史料确证","斯坦利《我如何找到利文斯通》；利文斯通日记"],["queen-victoria","henry-morton-stanley",1872,"维多利亚女王在邓罗宾城堡接见找到利文斯通归来的斯坦利。","史料确证","维多利亚女王日记"],["li-hongzhang","yan-fu",1880,"李鸿章创办北洋水师学堂，延严复任总教习。","史料确证","王栻《严复传》；《清史稿·严复传》"],["ito-hirobumi","li-hongzhang",1885,"伊藤博文赴天津与李鸿章谈判朝鲜问题，签订《天津会议专条》。","史料确证","《天津会议专条》；《李文忠公全集》"],["emperor-meiji","ito-hirobumi",1885,"明治天皇任命伊藤博文为首任内阁总理大臣。","史料确证","《明治天皇纪》"],["queen-victoria","otto-von-bismarck",1888,"维多利亚女王访问柏林期间在夏洛滕堡宫与俾斯麦会谈。","史料确证","维多利亚女王日记"],["kang-youwei","liang-qichao",1890,"梁启超拜康有为为师，就读万木草堂。","史料确证","梁启超《三十自述》"],["ito-hirobumi","li-hongzhang",1895,"李鸿章赴马关与伊藤博文议和，签订《马关条约》。","史料确证","《马关议和中日谈话录》"],["kang-youwei","zhang-zhidong",1895,"康有为赴江宁谒见署两江总督张之洞，张之洞资助上海强学会。","史料确证","康有为《康南海自编年谱》"],["queen-victoria","li-hongzhang",1896,"李鸿章出访英国期间在奥斯本宫觐见维多利亚女王。","史料确证","《李鸿章历聘欧美记》；维多利亚女王日记"],["otto-von-bismarck","li-hongzhang",1896,"李鸿章出访德国，赴弗里德里希斯鲁拜访已退休的俾斯麦。","史料确证","《李鸿章历聘欧美记》"],["liang-qichao","tan-sitong",1896,"梁启超与谭嗣同在北京相识，此后共同从事维新活动。","史料确证","梁启超《谭嗣同传》"],["liang-qichao","yan-fu",1897,"严复致书梁启超讨论《时务报》文章与变法，两人书信往来。","史料确证","严复《与梁启超书》"],["liang-qichao","cai-e",1897,"蔡锷考入长沙时务学堂，师从梁启超。","史料确证","梁启超《蔡松坡遗事》"],["kang-youwei","tan-sitong",1898,"百日维新期间谭嗣同与康有为在北京共同参与新政，事败后谭嗣同就义。","史料确证","梁启超《谭嗣同传》；康有为《康南海自编年谱》"],["kang-youwei","ito-hirobumi",1898,"伊藤博文访华期间，康有为往访请其进言光绪帝。","学界推测","康有为《康南海自编年谱》"],["sun-yat-sen","liang-qichao",1899,"孙中山与梁启超在日本多次会谈，商议两派合作。","史料确证","冯自由《革命逸史》；梁启超书信"],["sun-yat-sen","yan-fu",1905,"严复赴英处理开平矿务讼案，在伦敦与孙中山晤谈。","史料确证","王蘧常《严几道年谱》"],["sun-yat-sen","huang-xing",1905,"孙中山与黄兴等在东京组建中国同盟会。","史料确证","冯自由《革命逸史》；《黄兴年谱》"],["fridtjof-nansen","roald-amundsen",1907,"阿蒙森请求借用南森的“前进”号，南森放弃自己的极地计划而同意。","史料确证","阿蒙森《南极》；亨特福德《南森传》"],["sun-yat-sen","cai-yuanpei",1912,"孙中山就任临时大总统，任命蔡元培为教育总长。","史料确证","《临时政府公报》"],["cai-yuanpei","lu-xun",1912,"鲁迅应蔡元培之邀任南京临时政府教育部部员。","史料确证","许寿裳《亡友鲁迅印象记》；《鲁迅年谱》"],["mahatma-gandhi","rabindranath-tagore",1915,"甘地回印度后到圣蒂尼克坦拜访泰戈尔。","史料确证","甘地《自传》；泰戈尔书信"],["liang-qichao","cai-e",1915,"蔡锷与梁启超在天津密商讨袁，随后潜赴云南发动护国战争。","史料确证","梁启超《护国之役回顾谈》"],["liang-qichao","rabindranath-tagore",1924,"泰戈尔访华期间，梁启超主持讲学社接待并在北京致欢迎辞。","史料确证","梁启超《印度与中国文化之亲属的关系》"]];
